  '金沙': 'Arenas Doradas',  // PLAYERS[4]、FACTIONS.4.name

  // ── 阵营说明 ──
  '钢铁与工厂的工业强国，信奉火力与装甲。': 'Potencia industrial de acero y fábricas que confía en la potencia de fuego y el blindaje.',  // FACTIONS.1.culture
  '履带车辆防御 +5%；陆上单位在兵工厂的修理费 −20%。': 'Los vehículos de orugas tienen defensa +5%; precio de reparación de las unidades terrestres en fábricas −20%.',  // FACTIONS.1.trait
  '海洋与天空的联邦，重视技术与后勤。': 'Federación del mar y el cielo que valora la técnica y la logística.',  // FACTIONS.2.culture
  '航空单位和舰船视野 +1；航空单位在机场、舰船在港口的修理费 −20%。': 'Las unidades aéreas y los barcos tienen visión +1; precio de reparación de las unidades aéreas en aeropuertos y de los barcos en puertos −20%.',  // FACTIONS.2.trait
  '山林与雪原的游击之民，擅长地形与隐蔽。': 'Pueblo guerrillero de montes y llanuras nevadas, experto en el terreno y el ocultamiento.',  // FACTIONS.3.culture
  '步兵类单位造价 −5%；位于森林、山地的步兵类单位防御 +10%；中型坦克、重型坦克、火箭炮造价 +5%。': 'Los soldados tienen precio −5%; los soldados en bosques y montañas tienen defensa +10%; tanques medios, tanques pesados y lanzacohetes tienen precio +5%.',  // FACTIONS.3.trait
  '商路与黄金的城邦联盟，凭借财力与城墙作战。': 'Liga de ciudades-estado de rutas comerciales y oro que combate con su riqueza y sus murallas.',  // FACTIONS.4.culture
  '城市收入 +10%；位于建筑的单位防御 +5%，位于平原的单位防御 −5%。': 'Las ciudades tienen ingresos +10%; las unidades situadas en edificios tienen defensa +5% y las unidades situadas en llanuras, defensa −5%.',  // FACTIONS.4.trait

  // ── 阵营研究 ──
