AWI18n.add('es', {

  // ── 兵种名 ──
  '步兵': 'Infantería',  // UNITS.inf.name
  '步兵||move': 'A pie',  // 场合 move
  '破甲兵': 'Bazuca',  // UNITS.mech.name
  '狙击手': 'Francotirador',  // UNITS.snp.name
  '投弹手': 'Granadero',  // UNITS.grn.name
  '喷火兵': 'Lanzallamas',  // UNITS.flm.name
  '医护兵': 'Médico',  // UNITS.mdc.name
  '摩托兵': 'Moto',  // UNITS.bik.name
  '侦察车': 'Explorador',  // UNITS.rec.name
  '轻型坦克': 'Tanque ligero',  // UNITS.tnk.name
  '中型坦克': 'Tanque medio',  // UNITS.med.name
  '重型坦克': 'Tanque pesado',  // UNITS.hvy.name
  '自行火炮': 'Artillería',  // UNITS.art.name
  '火箭炮': 'Lanzacohetes',  // UNITS.rkt.name
  '防空车': 'Antiaéreo',  // UNITS.aa.name
  '防空导弹': 'Lanzamisiles',  // UNITS.sam.name
  '维修车': 'Taller móvil',  // UNITS.rep.name
  '运兵车': 'Portatropas',  // UNITS.apc.name
  '武装直升机': 'Heli de ataque',  // UNITS.cop.name
  '运输直升机': 'Heli de transporte',  // UNITS.tcp.name
  '攻击机': 'Avión de ataque',  // UNITS.atk.name
  '轰炸机': 'Bombardero',  // UNITS.bmb.name
  '战斗机': 'Caza',  // UNITS.ftr.name
  '炮艇': 'Cañonera',  // UNITS.gbt.name
  '驱逐舰': 'Destructor',  // UNITS.dst.name
  '潜艇': 'Submarino',  // UNITS.sub.name
  '战列舰': 'Acorazado',  // UNITS.bsh.name
  '登陆艇': 'Barcaza',  // UNITS.lnd.name

  // ── 兵种说明 ──
  '造价低廉，可占领建筑，可进入山地与河流。': 'Precio bajo. Puede capturar edificios y entrar en montañas y ríos.',  // UNITS.inf.desc
  '装备火箭筒的步兵，可占领建筑，对坦克伤害较高，在山地、河流上的移动消耗为 1。': 'Infantería armada con bazuca. Puede capturar edificios y causa daño alto a los tanques. Su consumo de movimiento en montañas y ríos es 1.',  // UNITS.mech.desc
  '射程 2–4 的远程步兵，擅长攻击步兵类单位，也可攻击轻型车辆和直升机。在山地上射程 +1。移动后不可攻击。': 'Soldado a distancia con alcance 2–4. Eficaz contra soldados; también puede atacar vehículos ligeros y helicópteros. Alcance +1 en montañas. No puede atacar después de moverse.',  // UNITS.snp.desc
  '射程 1–2，移动后仍可攻击。攻击时目标的地形防御减半，擅长攻击位于建筑、森林、山地的步兵类单位。攻击 2 格外的目标时不受反击。在山地上射程 +1。不可攻击航空单位和舰船，不可占领。': 'Alcance 1–2. Puede atacar después de moverse. Al atacar, la defensa de terreno del objetivo se reduce a la mitad; eficaz contra soldados situados en edificios, bosques y montañas. No recibe contraataque al atacar objetivos a 2 casillas. Alcance +1 en montañas. No puede atacar unidades aéreas ni barcos, ni capturar.',  // UNITS.grn.desc
  '射程 1，攻击时无视目标的地形防御，擅长攻击位于建筑、山地的步兵类单位。迷雾开启时，可发现周围 8 格森林、废墟中的隐蔽单位。不敌远程单位和车辆，不可攻击航空单位和舰船，不可占领。': 'Alcance 1. Al atacar, ignora la defensa de terreno del objetivo; eficaz contra soldados situados en edificios y montañas. Con niebla de guerra, detecta las unidades ocultas en bosques y ruinas de las 8 casillas que lo rodean. Débil ante unidades a distancia y vehículos. No puede atacar unidades aéreas ni barcos, ni capturar.',  // UNITS.flm.desc
  '无武装。相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名医护兵的效果不叠加。': 'Desarmado. Tus soldados adyacentes recuperan 2 HP por turno (sin pago de fondos). El efecto de varios médicos no se acumula.',  // UNITS.mdc.desc
  '乘坐摩托车的步兵，可占领建筑，移动力高，适合占领远处的建筑。不可进入山地。': 'Infantería en motocicleta. Puede capturar edificios; su movimiento alto sirve para capturar edificios lejanos. No puede entrar en montañas.',  // UNITS.bik.desc
  '陆上单位中移动力最高，擅长攻击步兵类单位和无掩护的火炮，不敌坦克。': 'La unidad terrestre con más movimiento. Eficaz contra soldados y artillería sin protección; débil ante los tanques.',  // UNITS.rec.desc
  '陆上主力，造价较低，攻击与防御均衡。': 'Fuerza principal en tierra. Precio bajo; ataque y defensa equilibrados.',  // UNITS.tnk.desc
  '攻击与防御高于轻型坦克，造价适中。': 'Más ataque y defensa que el tanque ligero. Precio moderado.',  // UNITS.med.desc
  '陆上单位中攻击与防御最高，造价高，移动力低。': 'La unidad terrestre con más ataque y defensa. Precio alto y movimiento bajo.',  // UNITS.hvy.desc
  '射程 2–3，可攻击舰船。移动后不可攻击，不可攻击相邻的敌方单位。': 'Alcance 2–3. Puede atacar barcos. No puede atacar después de moverse ni atacar unidades enemigas adyacentes.',  // UNITS.art.desc
  '射程 3–5，射程长于自行火炮，擅长攻击重型车辆。移动后不可攻击。': 'Alcance 3–5, mayor que el de la artillería. Eficaz contra vehículos pesados. No puede atacar después de moverse.',  // UNITS.rkt.desc
  '射程 1，擅长攻击航空单位，对步兵类单位伤害也较高。': 'Alcance 1. Eficaz contra unidades aéreas; también causa daño alto a los soldados.',  // UNITS.aa.desc
  '无武装。相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': 'Desarmado. Tus vehículos, unidades aéreas y barcos adyacentes recuperan 1 HP por turno (sin pago de fondos).',  // UNITS.rep.desc
  '移动不受地形影响，擅长攻击陆上单位，不敌防空车。': 'El terreno no afecta a su movimiento. Eficaz contra unidades terrestres; débil ante el antiaéreo.',  // UNITS.cop.desc
  '可攻击陆上单位和直升机，造价低于轰炸机。': 'Puede atacar unidades terrestres y helicópteros. Precio inferior al del bombardero.',  // UNITS.atk.desc
  '对陆上单位和舰船伤害极高，不可攻击航空单位。': 'Daño muy alto a unidades terrestres y barcos. No puede atacar unidades aéreas.',  // UNITS.bmb.desc
  '造价低廉的小型舰船，可攻击岸边的陆上单位，擅长攻击登陆艇。': 'Barco pequeño de precio bajo. Puede atacar unidades terrestres en la costa; eficaz contra barcazas.',  // UNITS.gbt.desc
  '兼具防空与反潜能力，擅长攻击潜艇和航空单位。': 'Combina defensa antiaérea y antisubmarina. Eficaz contra submarinos y unidades aéreas.',  // UNITS.dst.desc
  '射程 2–6，可攻击陆上单位和舰船，伤害较高。移动后不可攻击。': 'Alcance 2–6. Puede atacar unidades terrestres y barcos, con daño alto. No puede atacar después de moverse.',  // UNITS.bsh.desc
  '无武装。可搭载 2 个陆上单位，靠岸后卸载。': 'Desarmado. Puede cargar 2 unidades terrestres y descargarlas al llegar a la costa.',  // UNITS.lnd.desc
});

