  '抛射：移动后仍可攻击。': 'Tiro curvo: puede atacar después de moverse.',  // codex.js:169
  '不可攻击相邻的敌方单位，受到相邻敌方单位攻击时也不可反击。': 'No puede atacar unidades enemigas adyacentes ni contraatacar cuando lo ataca una unidad enemiga adyacente.',  // codex.js:170
