  '设有天数上限时，到期后先比较各队的收入建筑数，再比较单位总造价。': 'Con límite de días, al cumplirse se compara primero el número de edificios con ingresos de cada equipo y después el precio total de sus unidades.',  // codex.js:238
  '每座建筑有 20 点占领值，每次占领减去单位当前的 HP。满 HP 的单位需 2 回合完成占领。': 'Cada edificio tiene 20 puntos de captura; cada captura resta el HP actual de la unidad. Una unidad con HP al máximo completa la captura en 2 turnos.',  // codex.js:247
  '占领中的单位离开或被击毁时，占领值恢复为 20。不可占领友方的建筑。': 'Si la unidad que captura se va o es destruida, los puntos de captura vuelven a 20. No se pueden capturar edificios aliados.',  // codex.js:248
  '两个单位的 HP 相加，超过 10 的部分按造价返还资金。': 'Se suma el HP de las dos unidades; lo que pasa de 10 se devuelve en fondos según el precio.',  // codex.js:250
  '受到不相邻的敌方单位攻击时不可反击。': 'No se puede contraatacar a una unidad enemiga que ataca sin estar adyacente.',  // codex.js:260
  '己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': 'Tus unidades a 5 casillas o menos de un radar tuyo tienen ataque +10%. El efecto de varios radares no se acumula.',  // codex.js:276
  '迷雾开启时，己方雷达塔可看见周围 5 格。': 'Con niebla de guerra, tus radares ven 5 casillas alrededor.',  // codex.js:276
  '不提供收入。': 'No aporta ingresos.',  // codex.js:276
  '可占领建筑的兵种进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP。': 'Las unidades que capturan edificios pueden lanzarlo una vez al entrar: se elige una casilla como centro y todas las unidades a 2 casillas o menos pierden 3 HP.',  // codex.js:277
  '每击毁一个敌方单位，星级 +1，最高 3 星。': 'Cada unidad enemiga destruida da estrellas +1, hasta 3★.',  // codex.js:278
  '每 1 星攻击 +5%、防御 +5%。': 'Cada 1★ da ataque +5% y defensa +5%.',  // codex.js:278
  '运输单位移动后选择“卸载”，将搭载的单位放置到相邻且可进入的空格。卸载的单位本回合不可再行动。': 'Tras mover el transporte, se elige «Descargar» y se colocan las unidades cargadas en casillas libres adyacentes en las que puedan entrar. Las unidades descargadas no pueden actuar más ese turno.',  // codex.js:282
  '技能槽积满后，可在己方回合发动技能，效果持续至己方下回合开始。': 'Con la barra de poder llena, el poder se puede activar en tu turno; su efecto dura hasta el inicio de tu próximo turno.',  // codex.js:284
  '技能仅对己方阵营生效。各指挥官的技能见“指挥官”页。': 'El poder solo afecta a tu facción. Los poderes de cada comandante figuran en la página «Comandante».',  // codex.js:284
  '特长与阵营特性': 'Especialidad y rasgo de facción',  // codex.js:285
  '每位指挥官拥有一项特长，开局即生效。': 'Cada comandante tiene una especialidad, activa desde el inicio de la partida.',  // codex.js:286
  '指挥官同时具有所属阵营的特性，与本局军队的颜色无关。': 'El comandante tiene además el rasgo de su facción, sea cual sea el color de su ejército en la partida.',  // codex.js:287
  '研究点来源：研究经费、己方科研所，以及各阵营的研究方式（见“阵营”页）。': 'Origen de los puntos de investigación: el presupuesto de investigación, tus laboratorios y el método de investigación de cada facción (véase la página «Facción»).',  // codex.js:294
