  '支付研究经费获得研究点，解锁通用、阵营、指挥官三类科技。': 'Se paga presupuesto de investigación para obtener puntos de investigación y desbloquear tecnologías de tres clases: generales, de facción y de comandante.',  // ui-front.js:252
  '阵营数较少的队伍开局资金增加，每回合收入也略有增加。': 'Los equipos con menos facciones empiezan con más fondos y reciben algo más de ingresos por turno.',  // ui-front.js:252
  '三支及以上队伍对战时，击毁敌方单位可获得其造价的一部分资金。': 'En partidas de tres o más equipos, destruir una unidad enemiga aporta en fondos una parte de su precio.',  // ui-front.js:252
