  '海眼中心亮起一圈灯。那不是任何一国的灯。': 'En el centro del Ojo del Mar se enciende un anillo de luces. No son las luces de ninguna nación.',
  '（与荒地相同）。轮式车辆的移动消耗为 3。': ', igual que el páramo. El consumo de movimiento de los vehículos de ruedas es 3.',
