  '，与荒地相同。轮式车辆的移动消耗为 3。': ', ya recogido. Igual que el páramo. El consumo de movimiento de los vehículos de ruedas es 3.',
  '铁轨延伸': 'Vía prolongada',
  '陨星矿收入 +50%；每占领一座建筑，立即获得 50 资金。': 'Las minas de meteoro tienen ingresos +50%; cada edificio capturado aporta 50 fondos al instante.',
  '从海眼里出来的黑色军队，没有海岸线，靠矿井、铁路和大闸作战。': 'Ejército negro salido del Ojo del Mar, sin costa propia; combate con minas, ferrocarriles y la Gran Compuerta.',
