// ── 故事与战役（lore.js、campaign.js）及改名后重新对齐的条目 ──由 tools/i18n-story.js merge 回填，固定台词见 tools/I18N-GLOSSARY.md
AWI18n.add('es', {
  '收购。开个价，车归我了。': 'Adquisición. Pongan precio: el vehículo ya es mío.',
  '射程 3–6，只能攻击航空单位，伤害极高。移动后不可攻击。': 'Alcance 3–6. Solo puede atacar unidades aéreas, con daño muy alto. No puede atacar después de moverse.',
  '只能攻击航空单位，用于争夺制空权。': 'Solo puede atacar unidades aéreas. Sirve para disputar el dominio del aire.',
  '只能攻击舰船，擅长攻击战列舰。航空单位和战列舰不可攻击潜艇。不敌驱逐舰。': 'Solo puede atacar barcos; eficaz contra acorazados. Las unidades aéreas y los acorazados no pueden atacar submarinos. Débil ante el destructor.',
  '只能在道路、桥梁和建筑上移动。射程 1–3，移动后只能攻击相邻目标。可搭载 2 个徒步的步兵类单位（摩托兵除外）。攻击与防御介于中型坦克和重型坦克之间。': 'Solo circula por carreteras, puentes y casillas de edificio. Alcance 1–3; después de moverse solo puede atacar objetivos adyacentes. Puede cargar 2 soldados a pie (excepto motos). Su ataque y su defensa están entre los del tanque medio y los del tanque pesado.',
  '隐形的航空单位：敌方只有相邻时才能发现（迷雾关闭时也有效）。对航空单位伤害高，对陆上单位伤害中等。': 'Unidad aérea furtiva: el enemigo solo la detecta si está adyacente (también sin niebla de guerra). Daño alto a unidades aéreas y medio a unidades terrestres.',
  '射程 2–5 的舰船，移动后不可攻击。上一个己方回合没有攻击时处于下潜状态：敌方只有相邻时才能发现（迷雾关闭时也有效）。': 'Barco con alcance 2–5. No puede atacar después de moverse. Si no atacó en tu turno anterior, está sumergido: el enemigo solo lo detecta si está adyacente (también sin niebla de guerra).',
  '陆上单位结束移动停在这一格时拾取，获得 1–3 份陨星碎片（每个碎片堆在开局时随机决定），这一格变为碎片坑（与荒地相同）。轮式车辆的移动消耗为 3。': 'Una unidad terrestre que termina su movimiento en esta casilla lo recoge: se obtienen 1–3 fragmentos de meteoro (cantidad fijada al azar para cada montón al inicio de la partida) y la casilla se convierte en hoyo de fragmentos, igual que el páramo. El consumo de movimiento de los vehículos de ruedas es 3.',
  '迷雾开启时，森林中的单位只有相邻时才会被发现。': 'Con niebla de guerra, las unidades situadas en bosques solo se detectan desde una casilla adyacente.',
  '只有步兵类单位可以进入。狙击手、投弹手在山地上射程 +1。迷雾开启时，步兵类单位在山地上视野 +3。': 'Solo pueden entrar soldados. Francotiradores y granaderos tienen alcance +1 en montañas. Con niebla de guerra, los soldados tienen visión +3 en montañas.',
  '登陆艇可以进入。陆上单位可以在这里搭乘登陆艇；登陆艇可以在这里把搭载的单位卸载到相邻的格子。': 'Las barcazas pueden entrar. Las unidades terrestres pueden embarcar aquí en una barcaza; una barcaza situada aquí puede descargar sus unidades en las casillas adyacentes.',
  '只有舰船可以进入，移动消耗 2，地形防御 2 星。': 'Solo pueden entrar barcos. Consumo de movimiento 2, defensa de terreno 2★.',
  '每回合提供 3 研究点（每个阵营最多计 3 座）。停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。可以在这里研究科技。': 'Aporta 3 puntos de investigación por turno (cuentan 3 laboratorios como máximo por facción). Tus soldados situados aquí recuperan 2 HP por turno (con pago de fondos). Aquí se pueden investigar tecnologías.',
  '这一局没有开启科技': 'Esta partida no tiene tecnologías',
  '这一局关闭了指挥官特长': 'Especialidad de comandante desactivada en esta partida',
  '这一局关闭了指挥官技能': 'Poder de comandante desactivado en esta partida',
  '和「{name}」只能选一个': 'Solo se puede elegir esta o «{name}»',
  '要先解锁「{name}」': 'Desbloquea antes «{name}»',
  '只能在己方回合解锁科技': 'Solo se desbloquean tecnologías en tu turno',
  '这项科技不在己方的科技树里': 'Esta tecnología no está en tu árbol tecnológico',
  '这项科技已解锁': 'Esta tecnología ya está desbloqueada',
  '这里不能生产这个兵种': 'Aquí no se puede producir esta unidad',
  '这一格有单位': 'Hay una unidad en esta casilla',
  '这座建筑本回合已经生产过了': 'Este edificio ya produjo en este turno',
  '全军立即恢复 2 HP。己方下回合开始前：全军防御 +20%。': 'Todo tu ejército recupera 2 HP al instante. Hasta el inicio de tu próximo turno: todo tu ejército tiene defensa +20%.',
  '立即获得「己方建筑数 × 80」的资金，再加回合收入的 20%。': 'Se obtienen al instante fondos iguales a «edificios tuyos × 80», más el 20% de los ingresos por turno.',
  '所有敌方单位各损失 1 HP（不会被击毁）。有两个敌方阵营时各 0.8 HP，三个时各 0.7 HP。本回合：己方远程单位攻击 +30%。': 'Todas las unidades enemigas pierden 1 HP (no las destruye). Con dos facciones enemigas pierden 0.8 HP; con tres, 0.7 HP. Este turno: tus unidades a distancia tienen ataque +30%.',
  '全军立即恢复 2 HP（舰船 3 HP）。本回合：全军移动力 +1（舰船 +2），舰船对陆上单位伤害 +30%。己方下回合开始前：全军防御 +10%。': 'Todo tu ejército recupera 2 HP al instante (barcos 3 HP). Este turno: todo tu ejército tiene movimiento +1 (barcos +2) y los barcos tienen daño a unidades terrestres +30%. Hasta el inicio de tu próximo turno: todo tu ejército tiene defensa +10%.',
  '本回合：航空单位移动力 +2、攻击 +50%，攻击时不受反击。其他单位移动力 +2、攻击 +30%。': 'Este turno: las unidades aéreas tienen movimiento +2 y ataque +50%, y no reciben contraataque al atacar. Las demás unidades tienen movimiento +2 y ataque +30%.',
  '本回合：各型坦克移动力 +2、攻击 +50%，攻击后可再移动。己方下回合开始前：各型坦克防御 +20%。': 'Este turno: los tanques ligeros, medios y pesados tienen movimiento +2 y ataque +50%, y pueden moverse de nuevo tras atacar. Hasta el inicio de tu próximo turno: los tanques ligeros, medios y pesados tienen defensa +20%.',
  '最多 4 座没有单位的己方城市各出现一个满 HP 的步兵，当回合可行动。本回合：步兵类单位攻击 +30%、移动力 +1。': 'Aparece una infantería con HP al máximo en hasta 4 ciudades tuyas sin unidades; puede actuar ese mismo turno. Este turno: los soldados tienen ataque +30% y movimiento +1.',
  '本回合：全军攻击 +20%。己方下回合开始前：敌方单位视野降为 1。迷雾关闭时，敌方只能发现自己单位 2 格内的己方单位。': 'Este turno: todo tu ejército tiene ataque +20%. Hasta el inicio de tu próximo turno: la visión de las unidades enemigas baja a 1. Sin niebla de guerra, el enemigo solo detecta tus unidades a 2 casillas o menos de las suyas.',
  '本回合：全军移动力 +2，攻击时不受反击。': 'Este turno: todo tu ejército tiene movimiento +2 y no recibe contraataque al atacar.',
  '己方下回合开始前：己方反击伤害 ×2，全军防御 +20%。': 'Hasta el inicio de tu próximo turno: tu daño de contraataque es ×2 y todo tu ejército tiene defensa +20%.',
  '己方下回合开始前：敌方单位移动力 −3（最低 1）、视野 −2，己方全军防御 +20%。': 'Hasta el inicio de tu próximo turno: las unidades enemigas tienen movimiento −3 (mínimo 1) y visión −2, y todo tu ejército tiene defensa +20%.',
  '本回合：HP 未满的己方单位攻击 +50%，全军移动力 +1。': 'Este turno: tus unidades sin HP al máximo tienen ataque +50% y todo tu ejército tiene movimiento +1.',
  '本回合：全军攻击 +20%（舰船 +40%）、移动力 +2。己方下回合开始前：敌方舰船移动力 −3（最低 1），不能在港口修理。': 'Este turno: todo tu ejército tiene ataque +20% (barcos +40%) y movimiento +2. Hasta el inicio de tu próximo turno: los barcos enemigos tienen movimiento −3 (mínimo 1) y no pueden repararse en puertos.',
  '己方下回合开始前：敌方单位在道路、桥梁上的移动消耗 +2（航空单位除外）。本回合：己方车辆攻击 +30%。': 'Hasta el inicio de tu próximo turno: el consumo de movimiento de las unidades enemigas en carreteras y puentes es +2 (excepto unidades aéreas). Este turno: tus vehículos tienen ataque +30%.',
  '解锁黑潮后可查看。完成任意一组条件就能解锁：': 'Disponible al desbloquear la Marea Sombría. Basta con completar una de las vías:',
  '所有阵营都能研究。': 'Todas las facciones pueden investigarlas.',
  '两条科技线的第 3 级只能选一条。': 'Solo se puede elegir el nivel 3 de una de las dos líneas.',
  '司令部被占领时，败北阵营的单位全部消失，建筑归占领方所有。全部单位被击毁时，这个阵营的建筑全部变为中立。': 'Cuando se captura el cuartel general, todas las unidades de la facción derrotada desaparecen y sus edificios pasan a quien lo capturó. Cuando se destruyen todas sus unidades, todos los edificios de esa facción pasan a ser neutrales.',
  '每座收入建筑每回合提供 {n} 资金，在回合开始时获得。这个数值可以在开局设置里调整。': 'Cada edificio con ingresos aporta {n} fondos por turno, que se obtienen al inicio del turno. Este valor se puede cambiar en los ajustes de partida.',
  '把单位移动到同兵种、HP 未满的己方单位所在的格子，选择“合并”。': 'Se mueve la unidad a la casilla de otra unidad tuya del mismo tipo sin HP al máximo y se elige «Unir».',
  '两个单位都是强化单位，合并后才保留强化。': 'El refuerzo solo se conserva tras unir si las dos unidades estaban reforzadas.',
  '攻击加成：位于己方{tower} 5 格范围内时 +10%，单位每 1 星 +5%，再加上指挥官的修正。': 'Bonificación de ataque: +10% a 5 casillas o menos de un edificio tuyo ({tower}), +5% por cada 1★ de la unidad, más los modificadores del comandante.',
  '攻击加成：单位每 1 星 +5%，再加上指挥官的修正。': 'Bonificación de ataque: +5% por cada 1★ de la unidad, más los modificadores del comandante.',
  '防御加成：单位每 1 星 +5%，再加上指挥官的修正，最高 70%。': 'Bonificación de defensa: +5% por cada 1★ de la unidad, más los modificadores del comandante, hasta 70%.',
  '受到不相邻的敌方单位攻击时不可反击。{list}受到相邻敌方单位攻击时也不可反击。': 'No se puede contraatacar a una unidad enemiga que ataca sin estar adyacente. Tampoco pueden contraatacar a una unidad enemiga adyacente: {list}.',
  '不可攻击对方兵种的单位也不可反击。': 'Una unidad que no puede atacar al tipo de unidad que la ataca tampoco puede contraatacar.',
  '回合开始时，停留在己方建筑的单位恢复 2 HP，每恢复 1 HP 需支付造价 10% 的资金；资金不足时只恢复 1 HP。': 'Al inicio del turno, las unidades situadas en edificios tuyos recuperan 2 HP; cada 1 HP recuperado cuesta en fondos el 10% del precio de la unidad; con fondos insuficientes solo se recupera 1 HP.',
  '每座只能使用一次，敌我单位都受影响。运输单位搭载的单位不受影响。': 'Cada silo se usa una sola vez y afecta a unidades de ambos bandos. No afecta a las unidades cargadas en un transporte.',
  '把单位移动到己方运输单位所在的格子就能搭载。友方的运输单位不能搭载己方单位。': 'Para cargar una unidad, basta con moverla a la casilla de un transporte tuyo. Los transportes aliados no pueden cargar tus unidades.',
  '攻击和受到攻击都能积累技能槽，积累量按损失的造价计算，受到攻击时是攻击时的 2 倍。': 'La barra de poder se carga al atacar y al recibir ataques; la carga se calcula según el precio perdido, y al recibir ataques es 2 veces la de atacar.',
  '在己方{a}或{b}可以研究科技。': 'Las tecnologías se pueden investigar en edificios tuyos: {a} o {b}.',
  '在己方{a}可以研究科技。': 'Las tecnologías se pueden investigar en un edificio tuyo: {a}.',
  '每个阵营可研究 6 条科技线：通用 3 条、阵营 2 条、指挥官 1 条。每条科技线分 3 级，要按顺序解锁。': 'Cada facción puede investigar 6 líneas de tecnología: 3 generales, 2 de facción y 1 de comandante. Cada línea tiene 3 niveles, que hay que desbloquear en orden.',
  '解锁科技需要研究点。研究点在每回合开始时获得，可以一直攒着。': 'Para desbloquear tecnologías hacen falta puntos de investigación. Se obtienen al inicio de cada turno y se pueden ir guardando.',
  '研究点够一项科技所需的点数时，就能在己方回合立即解锁，当回合生效；一回合可以连续解锁多项。': 'Cuando los puntos de investigación alcanzan para una tecnología, se puede desbloquear al momento en tu turno y surte efecto ese mismo turno; en un turno se pueden desbloquear varias seguidas.',
  '阵营 2 条科技线的第 3 级只能选一条。': 'Del nivel 3 de las 2 líneas de facción solo se puede elegir uno.',
  '陆上单位结束移动停留在{shard}上就能拾取，获得 {min}–{max} 份（每个碎片堆在开局时随机决定），这一格变为{pit}。航空单位不拾取。': 'Una unidad terrestre que termina su movimiento en una casilla de {shard} recoge su contenido: se obtienen {min}–{max} fragmentos (cantidad fijada al azar para cada montón al inicio de la partida) y la casilla pasa a ser {pit}. Las unidades aéreas no recogen.',
  '{name}已采完，变为山地': '{name} se ha agotado y se ha convertido en montaña',
  '两个单位合并时，只要有一方是强化单位，合并后就是强化单位。双方都是强化单位时，返还其中一个单位的强化价。': 'Al fusionar dos unidades, el resultado queda reforzado si cualquiera de las dos lo estaba. Si ambas estaban reforzadas, se devuelve el coste de refuerzo de una de ellas.',
  '可以在开局规则里关闭{res}。': 'En las reglas de inicio se puede desactivar este recurso ({res}).',
  '刚生产的单位，在做下一个动作之前可以按取消键撤回，资金和{res}全额返还。': 'Una unidad recién producida se puede deshacer con el botón de cancelar antes de hacer la siguiente acción; se devuelven todos los fondos y {res}.',
  '单位移动后如果没有遇伏，也没有发现新的敌方单位，可以按取消键撤回这一步。': 'Si una unidad se movió sin caer en una emboscada y sin descubrir unidades enemigas nuevas, ese movimiento se puede deshacer con el botón de cancelar.',
  '做了下一个动作之后不能撤回。': 'Después de hacer la siguiente acción ya no se puede deshacer.',
  '迷雾开启时，只能看见己方和友方的单位、建筑周围的格子。': 'Con niebla de guerra, solo se ven las casillas alrededor de las unidades y los edificios tuyos y aliados.',
  '位于{list}的单位（航空单位除外）处于隐蔽状态，只有相邻时才会被发现。': 'Las unidades situadas en casillas de {list} (excepto unidades aéreas) están ocultas y solo se detectan desde una casilla adyacente.',
  '{sub}在任何位置都只有相邻时才会被发现，{dst}可以在 2 格内发现它。': '{sub}: en cualquier posición solo se detecta desde una casilla adyacente; {dst}: puede detectarlo a 2 casillas o menos.',
  '{sub}在任何位置都只有相邻时才会被发现。': '{sub}: en cualquier posición solo se detecta desde una casilla adyacente.',
  '只能攻击看得见的目标。移动中遇到没有发现的敌方单位时停止移动（遇伏），这个单位本回合行动结束。': 'Solo se pueden atacar objetivos visibles. Una unidad que encuentra al moverse una unidad enemiga sin detectar se detiene (emboscada) y su acción termina ese turno.',
  '每张地图有 2–4 个阵营，按{list}的顺序行动。各阵营可以各自为战，也可以结盟组队。': 'Cada mapa tiene 2–4 facciones, que actúan en este orden: {list}. Las facciones pueden combatir cada una por su cuenta o aliarse en equipos.',
  '每张地图有 2–4 个阵营。各阵营可以各自为战，也可以结盟组队。': 'Cada mapa tiene 2–4 facciones. Las facciones pueden combatir cada una por su cuenta o aliarse en equipos.',
  '战利品：三支及以上队伍对战时，击毁敌方单位可立即获得它造价 {pct}% 的资金。': 'Botín: en partidas de tres o más equipos, destruir una unidad enemiga aporta al instante el {pct}% de su precio en fondos.',
  '{name}阵营、指挥官和精锐兵种要解锁后才能在自由对局中使用。完成下面任意一组条件就能解锁。': 'La facción {name}, sus comandantes y sus unidades de élite hay que desbloquearlos para usarlos en partida libre. Basta con completar una de las vías siguientes.',
  '这一关的地图「{name}」还没做好。': 'El mapa de esta misión, «{name}», todavía no está listo.',
  '这一关的地图还没做好': 'El mapa de esta misión todavía no está listo',
  '这一关暂时不能开始': 'Esta misión no se puede iniciar por ahora',
  '按任意键开始': 'Pulsa cualquier tecla',
  '点击屏幕开始': 'Toca la pantalla',
  '2–4 个阵营': '2–4 facciones',
  '这张地图没有简介。': 'Este mapa no tiene descripción.',
  '这张地图暂时不能使用，请选择其他地图。': 'Este mapa no se puede usar por ahora; elige otro mapa.',
  '所有阵营都在同一队，至少要分成两队。': 'Todas las facciones están en el mismo equipo; hacen falta al menos dos equipos.',
  '完成任意一组条件就能解锁：': 'Basta completar una vía para desbloquear:',
  '开局时从这个阵营里随机选出一位指挥官。': 'Al empezar la partida se elige al azar un comandante de esta facción.',
  '这张地图的推荐设置：{list}': 'Ajustes recomendados para este mapa: {list}',
  '对局进度会自动保存，可以在标题画面选“继续”接着进行。': 'La partida se guarda sola; se puede retomar con «Continuar» en la pantalla de título.',
  '每个提示都可以点击': 'Todas las ayudas se pueden tocar',
  '移动消耗都是 1': 'Consumo de movimiento 1',
  '开阔地形，陆上单位都能进入，地形防御 1 星。': 'Terreno abierto. Pueden entrar todas las unidades terrestres. Defensa de terreno 1★.',
  '陆上单位的移动消耗都是 1，没有地形防御。': 'El consumo de movimiento de las unidades terrestres es 1. Sin defensa de terreno.',
  '跨越河流的道路，陆上单位的移动消耗都是 1，没有地形防御。': 'Carretera que cruza un río. El consumo de movimiento de las unidades terrestres es 1. Sin defensa de terreno.',
  '徒步的步兵类单位可以进入，车辆和摩托兵不能进入。': 'Pueden entrar los soldados a pie; los vehículos y las motos no pueden entrar.',
  '只有舰船和航空单位可以进入。': 'Solo pueden entrar barcos y unidades aéreas.',
  '地形防御 2 星，车辆的移动消耗是 2。': 'Defensa de terreno 2★. El consumo de movimiento de los vehículos es 2.',
  '可以在这里研究科技。': 'Aquí se pueden investigar tecnologías.',
  '通关下面任意一关，同时解锁这位指挥官。': 'Superar cualquiera de estas misiones desbloquea además a este comandante.',
  '电脑要在普通难度以上。': 'La CPU debe estar en dificultad normal o superior.',
  '要先解锁前一级': 'Desbloquea antes el nivel anterior',
  '研究点够一项科技所需的点数时就能立即解锁，一回合可以连续解锁多项。': 'Cuando los puntos de investigación alcanzan para una tecnología, se puede desbloquear al momento; en un turno se pueden desbloquear varias seguidas.',
  '现在不能解锁这项科技': 'Ahora no se puede desbloquear esta tecnología',
  '这张地图暂时不能使用（地图文件可能正在修改），请选择其他地图。': 'Este mapa no se puede usar por ahora (puede que su archivo esté en edición); elige otro mapa.',
  '这张地图需要 {n} 个阵营，现在不能开始对局，请选择其他地图。': 'Este mapa requiere {n} facciones y ahora no se puede iniciar la partida. Elige otro mapa.',
  '这张地图暂时不能使用。': 'Este mapa no se puede usar por ahora.',
  '要返回标题吗？': '¿Volver al título?',
  '要认输吗？': '¿Rendirse?',
  '要出售这个单位吗？': '¿Vender esta unidad?',
  '还差{list}': 'Faltan: {list}',
  '车辆移动力 +1。步兵类单位攻击 −10%。': 'Los vehículos tienen movimiento +1. Los soldados tienen ataque −10%.',
  '位于 2 星及以上地形或建筑的单位防御 +20%。全军攻击 −10%。': 'Las unidades situadas en terreno de 2★ o más o en edificios tienen defensa +20%. Todo tu ejército tiene ataque −10%.',
  '所有单位造价 −10%。全军攻击 −10%。': 'Todas las unidades tienen precio −10%. Todo tu ejército tiene ataque −10%.',
  '自行火炮、火箭炮攻击 +40%。其他远程单位攻击 +20%。': 'Artillería y lanzacohetes tienen ataque +40%. Las demás unidades a distancia tienen ataque +20%.',
  '舰船攻击 +30%、防御 +20%、移动力 +1、造价 −15%，在港口修理免费。步兵类单位攻击 +10%。': 'Los barcos tienen ataque +30%, defensa +20%, movimiento +1 y precio −15%, y su reparación en puertos es gratis. Los soldados tienen ataque +10%.',
  '攻击机、轰炸机、战斗机攻击 +30%、造价 −20%。': 'Aviones de ataque, bombarderos y cazas tienen ataque +30% y precio −20%.',
  '各型坦克攻击 +30%、防御 +10%。其他单位攻击 −15%。': 'Los tanques ligeros, medios y pesados tienen ataque +30% y defensa +10%. Las demás unidades tienen ataque −15%.',
  '步兵类单位攻击 +30%、防御 +10%、占领值 ×1.5、视野 +1。车辆造价 +10%。': 'Los soldados tienen ataque +30%, defensa +10%, puntos de captura ×1.5 y visión +1. Los vehículos tienen precio +10%.',
  '武装直升机攻击 +40%、防御 +20%、造价 −20%。运输直升机移动力 +2、搭载数 +1。舰船攻击和防御 −20%。': 'El heli de ataque tiene ataque +40%, defensa +20% y precio −20%. El heli de transporte tiene movimiento +2 y capacidad +1. Los barcos tienen ataque y defensa −20%.',
  '狙击手射程 +1、攻击 +40%、造价 −20%，移动后可攻击，击毁目标后可再行动（每回合一次）。投弹手攻击 +25%，其他步兵类单位攻击 +15%。全军视野 +1。位于森林、山地的己方单位防御 +15%。': 'El francotirador tiene alcance +1, ataque +40% y precio −20%, puede atacar después de moverse y puede actuar de nuevo tras destruir a su objetivo (una vez por turno). El granadero tiene ataque +25% y los demás soldados, ataque +15%. Todo tu ejército tiene visión +1. Tus unidades situadas en bosques y montañas tienen defensa +15%.',
  '新生产的单位当回合可行动。所有单位造价 +10%。': 'Las unidades recién producidas pueden actuar ese mismo turno. Todas las unidades tienen precio +10%.',
  '直射单位攻击 +5%，攻击后可用剩余移动力再移动，但不能再攻击或占领。': 'Las unidades de fuego directo tienen ataque +5% y, tras atacar, pueden moverse de nuevo con el movimiento restante, pero no atacar ni capturar otra vez.',
  '己方单位每回合开始时恢复 1 HP，在建筑上修理免费。全军攻击 −10%。': 'Tus unidades recuperan 1 HP al inicio de cada turno, y su reparación en edificios es gratis. Todo tu ejército tiene ataque −10%.',
  '己方单位被相邻的敌方单位攻击时先手反击：先反击，敌方再按剩余 HP 攻击。己方主动攻击时攻击 −10%。': 'Una unidad tuya atacada por una unidad enemiga adyacente realiza un contraataque anticipado: primero contraataca y después la unidad enemiga ataca con el HP que le queda. Al iniciar el ataque, tus unidades tienen ataque −10%.',
  '防空车、防空导弹、战斗机对航空单位伤害 +40%、视野 +2、造价 −25%。防空车对陆上单位伤害 +40%、防御 +15%、移动力 +1。直升机、攻击机、轰炸机攻击 −15%。': 'Antiaéreos, lanzamisiles y cazas tienen daño a unidades aéreas +40%, visión +2 y precio −25%. El antiaéreo tiene daño a unidades terrestres +40%, defensa +15% y movimiento +1. Helicópteros, aviones de ataque y bombarderos tienen ataque −15%.',
  '潜艇攻击 +40%、造价 −20%，只有相邻时才会被发现。驱逐舰、炮艇攻击 +20%、造价 −15%。步兵类单位攻击 +25%，车辆攻击 +10%。': 'El submarino tiene ataque +40% y precio −20%, y solo se detecta desde una casilla adyacente. Destructores y cañoneras tienen ataque +20% y precio −15%. Los soldados tienen ataque +25% y los vehículos, ataque +10%.',
  '侦察车、摩托兵、运兵车移动力 +3。侦察车、摩托兵攻击 +60%，攻击后可用剩余移动力再移动。中型、重型坦克造价 +10%。': 'Exploradores, motos y portatropas tienen movimiento +3. Exploradores y motos tienen ataque +60% y, tras atacar, pueden moverse de nuevo con el movimiento restante. Los tanques medios y pesados tienen precio +10%.',
  '喷火兵、破甲兵攻击 +50%、移动力 +1、造价 −20%。远程单位攻击 −10%。': 'Lanzallamas y bazucas tienen ataque +50%, movimiento +1 y precio −20%. Las unidades a distancia tienen ataque −10%.',
  '己方单位在能进入的地形上移动消耗都是 1。步兵类单位移动力 +1。': 'El consumo de movimiento de tus unidades es 1 en todo terreno en el que pueden entrar. Los soldados tienen movimiento +1.',
  '己方单位的攻击不随 HP 减少而降低。修理费 ×2。': 'El ataque de tus unidades no baja al perder HP. Precio de reparación ×2.',
  '己方城市也可以生产步兵类单位。步兵类单位造价 −20%、攻击 +10%。': 'Tus ciudades también pueden producir soldados. Los soldados tienen precio −20% y ataque +10%.',
  '各型坦克、深渊战车、装甲列车攻击 +15%。位于陨星矿、荒地、废墟的己方单位防御 +20%，每回合恢复 1 HP。己方陨星矿收入 +50%。': 'Los tanques ligeros, medios y pesados, el tanque abisal y el tren blindado tienen ataque +15%. Tus unidades situadas en minas de meteoro, páramos y ruinas tienen defensa +20% y recuperan 1 HP por turno. Tus minas de meteoro dan ingresos +50%.',
  '舰船攻击 +20%、移动力 +1。远程单位攻击 +15%。己方单位在沙滩上的移动消耗为 1。迷雾开启时，视野范围内海洋、沙滩、礁石上的敌方单位都可见，礁石的隐蔽对其无效（潜艇除外）。': 'Los barcos tienen ataque +20% y movimiento +1. Las unidades a distancia tienen ataque +15%. El consumo de movimiento de tus unidades en playas es 1. Con niebla de guerra, las unidades enemigas en mar, playas y arrecifes dentro de tu visión son visibles, y los arrecifes no las ocultan de ti (excepto submarinos).',
  '所有单位造价 −15%。每击毁一个敌方单位，获得它造价 30% 的资金。': 'Todas las unidades tienen precio −15%. Por cada unidad enemiga destruida se obtienen fondos por el 30% de su precio.',
  '车辆攻击 +10%，在道路、桥梁上防御 +15%。回合开始时位于道路、桥梁的车辆本回合移动力 +2。装甲列车造价 −20%。': 'Los vehículos tienen ataque +10% y, en carreteras y puentes, defensa +15%. Los vehículos que empiezan el turno en una carretera o un puente tienen movimiento +2 ese turno. El tren blindado tiene precio −20%.',
  '汀鹭的修理本来就免费，只有“额外恢复 1 HP”有效': 'La reparación de Ting Lu ya es gratis: solo se aplica «1 HP adicional»',
  '每座兵工厂每回合可生产 2 个单位（要先把第一个单位移出建筑）；重型坦克造价 −20%。': 'Cada fábrica puede producir 2 unidades por turno (antes hay que sacar del edificio la primera unidad); el tanque pesado tiene precio −20%.',
  '沧澜的舰船在港口修理本来就免费，只有“舰船造价 −10%”有效': 'La reparación de los barcos de Cang Lan en puertos ya es gratis: solo se aplica «precio de los barcos −10%»',
  '步兵类单位在森林、山地、沼泽上的移动消耗都是 1。': 'El consumo de movimiento de los soldados en bosques, montañas y pantanos es 1.',
  '雪杉的单位在可进入地形上的移动消耗本来就都是 1': 'El consumo de movimiento de las unidades de Xue Shan ya es 1 en todo terreno en el que pueden entrar',
  '每个己方回合开始时，己方城市、司令部、碉堡使相邻且可见的敌方单位各损失 1 HP（不会被击毁；每个单位每回合只受一次）。': 'Al inicio de cada turno tuyo, tus ciudades, cuarteles generales y búnkeres hacen perder 1 HP a cada unidad enemiga adyacente y visible (no las destruye; cada unidad lo sufre una sola vez por turno).',
  '侦察车、轻型坦克、防空车移动力再 +1。': 'Exploradores, tanques ligeros y antiaéreos tienen otro +1 de movimiento.',
  '运兵车移动力 +1、搭载数 +1。步兵类单位的攻击减益减为 −5%。': 'El portatropas tiene movimiento +1 y capacidad +1. La penalización de ataque de los soldados baja a −5%.',
  '强化技能「闪击」，其他效果保留。本回合：侦察车、防空车和各型坦克击毁目标后可再行动一次，全军最多 4 次。': 'Mejora el poder «Relámpago»; los demás efectos se mantienen. Este turno: exploradores, antiaéreos y los tanques ligeros, medios y pesados pueden actuar una vez más tras destruir a su objetivo, hasta 4 veces entre todo tu ejército.',
  '远程单位的运气范围变为 5–9（原来 0–9）。自行火炮、火箭炮视野 +2。': 'El rango de suerte de las unidades a distancia pasa a ser 5–9 (antes 0–9). Artillería y lanzacohetes tienen visión +2.',
  '自行火炮移动后可以攻击距离 2 格的目标，这次攻击 −30%。': 'La artillería puede atacar después de moverse a objetivos a 2 casillas de distancia; ese ataque tiene −30%.',
  '强化技能「炮火覆盖」，其他效果保留。本回合：己方远程单位射程 +1。': 'Mejora el poder «Bombardeo masivo»; los demás efectos se mantienen. Este turno: tus unidades a distancia tienen alcance +1.',
  '各型坦克在森林、废墟、荒地上的移动消耗为 1。': 'El consumo de movimiento de los tanques ligeros, medios y pesados en bosques, ruinas y páramos es 1.',
  '与己方坦克相邻的其他陆上单位，攻击和反击时没有攻击 −15% 的减益。': 'Las demás unidades terrestres adyacentes a un tanque tuyo no tienen la penalización de ataque −15% al atacar ni al contraatacar.',
  '强化技能「履带洪流」，其他效果保留。发动时，最多 2 座没有单位的己方兵工厂各出现一辆 5 HP 的轻型坦克，当回合可行动。': 'Mejora el poder «Alud de orugas»; los demás efectos se mantienen. Al activarlo, aparece un tanque ligero con 5 HP en hasta 2 fábricas tuyas sin unidades; puede actuar ese mismo turno.',
  '己方单位被敌方击毁时，返还它造价的 10%。': 'Cuando el enemigo destruye una unidad tuya, se devuelve el 10% de su precio.',
  '强化技能「加班」，其他效果保留。本回合：单位造价 −40%，每座生产建筑可生产 3 次。': 'Mejora el poder «Horas extra»; los demás efectos se mantienen. Este turno: las unidades tienen precio −40% y cada edificio de producción puede producir 3 veces.',
  '主动攻击 HP 比自己低的敌方单位时，没有攻击 −10% 的减益。': 'Al iniciar el ataque contra una unidad enemiga con menos HP que la unidad atacante, no se aplica la penalización de ataque −10%.',
  '不发动技能时，喷火兵攻击后也会把目标所在的森林变为荒地。': 'Sin activar el poder, el ataque del lanzallamas también convierte en páramo el bosque del objetivo.',
  '强化技能「燎原」，其他效果保留。本回合：破甲兵攻击也有溅射。每个敌方单位每回合因溅射最多损失 5 HP。': 'Mejora el poder «Tierra quemada»; los demás efectos se mantienen. Este turno: el ataque del bazuca también causa daño en área. Cada unidad enemiga pierde como máximo 5 HP por turno por daño en área.',
  '舰船在礁石上的移动消耗为 1。位于礁石、港口的舰船防御 +10%。': 'El consumo de movimiento de los barcos en arrecifes es 1. Los barcos situados en arrecifes y puertos tienen defensa +10%.',
  '登陆艇搭载数 +1。位于沙滩的己方陆上单位防御 +20%。': 'La barcaza tiene capacidad +1. Tus unidades terrestres situadas en playas tienen defensa +20%.',
  '强化技能「怒潮」，其他效果保留。本回合：战列舰移动后可以攻击，射程 2–4。': 'Mejora el poder «Marea furiosa»; los demás efectos se mantienen. Este turno: el acorazado puede atacar después de moverse, con alcance 2–4.',
  '攻击机、轰炸机、战斗机也可以在己方城市修理。': 'Aviones de ataque, bombarderos y cazas también pueden repararse en tus ciudades.',
  '强化技能「俯冲」，其他效果保留。己方下回合开始前：只有敌方战斗机、防空导弹、防空车能攻击己方攻击机、轰炸机、战斗机。': 'Mejora el poder «Picado»; los demás efectos se mantienen. Hasta el inicio de tu próximo turno: solo los cazas, lanzamisiles y antiaéreos enemigos pueden atacar a tus aviones de ataque, bombarderos y cazas.',
  '直升机可以发现周围 8 格森林、废墟中的隐蔽单位。武装直升机对步兵类单位伤害 +10%。': 'Los helicópteros detectan las unidades ocultas en bosques y ruinas de las 8 casillas que los rodean. El heli de ataque tiene daño a soldados +10%.',
  '回合开始时已在运输直升机上的步兵类单位，卸载后当回合还能攻击或占领，但不能移动。': 'Los soldados que ya iban en un heli de transporte al inicio del turno pueden atacar o capturar ese mismo turno tras descargarse, pero no moverse.',
  '强化技能「蜂群」，其他效果保留。本回合：武装直升机攻击时，目标每与一架己方直升机相邻，攻击 +10%，最多 +30%。': 'Mejora el poder «Enjambre»; los demás efectos se mantienen. Este turno: cuando ataca un heli de ataque, tiene ataque +10% por cada helicóptero tuyo adyacente al objetivo, hasta +30%.',
  '回合开始时，HP 不高于 4 的单位多恢复 1 HP。': 'Al inicio del turno, las unidades con 4 HP o menos recuperan 1 HP más.',
  '满 HP 的己方单位没有攻击 −10% 的减益。': 'Tus unidades con HP al máximo no tienen la penalización de ataque −10%.',
  '强化技能「急救」，其他效果保留。恢复量提高到 3 HP。复活最近被击毁的 2 个单位，各 4 HP。每个单位每局只能复活一次。': 'Mejora el poder «Primeros auxilios»; los demás efectos se mantienen. La recuperación sube a 3 HP. Reviven tus últimas 2 unidades destruidas, con 4 HP cada una. Cada unidad solo puede revivir una vez por partida.',
  '防空导弹射程 +1。防空车、防空导弹、战斗机视野再 +1。': 'El lanzamisiles tiene alcance +1. Antiaéreos, lanzamisiles y cazas tienen otro +1 de visión.',
  '强化技能「天网」，其他效果保留。被“天网”攻击的敌方航空单位立即结束行动。': 'Mejora el poder «Red celeste»; los demás efectos se mantienen. La unidad aérea enemiga atacada por «Red celeste» termina su acción de inmediato.',
  '上回合没有移动的潜艇，本回合第一次攻击 +20%。': 'El submarino que no se movió en el turno anterior tiene +20% en su primer ataque de este turno.',
  '潜艇攻击后可用剩余移动力再移动。': 'Tras atacar, el submarino puede moverse de nuevo con el movimiento restante.',
  '强化技能「狼群」，其他效果保留。本回合：潜艇可以穿过敌方舰船所在的格子。': 'Mejora el poder «Manada»; los demás efectos se mantienen. Este turno: los submarinos pueden atravesar casillas con barcos enemigos.',
  '强化技能「全民皆兵」，其他效果保留。出现步兵的城市增加到最多 6 座，步兵初始为 1 星。': 'Mejora el poder «Pueblo en armas»; los demás efectos se mantienen. La infantería aparece en hasta 6 ciudades y empieza con 1★.',
  '投弹手击毁目标后也可再行动（每回合一次）。': 'El granadero también puede actuar de nuevo tras destruir a su objetivo (una vez por turno).',
  '狙击手被相邻的敌方单位攻击时可以反击，伤害是正常的 50%。': 'El francotirador puede contraatacar cuando lo ataca una unidad enemiga adyacente, con el 50% del daño normal.',
  '强化技能「一击」，其他效果保留。本回合：每个狙击手击毁目标后可连续再行动，最多 3 次。': 'Mejora el poder «Un disparo»; los demás efectos se mantienen. Este turno: cada francotirador puede actuar de nuevo cada vez que destruye a su objetivo, hasta 3 veces.',
  '敌方单位遇伏时，伏击它的己方单位先攻击一次，不受反击。每个己方单位每个敌方回合一次。': 'Cuando una unidad enemiga cae en una emboscada, la unidad tuya que la embosca ataca primero una vez y no recibe contraataque. Una vez por unidad tuya en cada turno enemigo.',
  '强化技能「灯火管制」，其他效果保留。持续时间延长到 2 个敌方回合。迷雾关闭时，敌方只能发现相邻的己方单位。生效期间技能槽不积累。': 'Mejora el poder «Apagón»; los demás efectos se mantienen. La duración sube a 2 turnos enemigos. Sin niebla de guerra, el enemigo solo detecta tus unidades adyacentes. La barra de poder no se carga mientras el poder está activo.',
  '攻击后再移动时，剩余移动力 +1。': 'Al moverse de nuevo tras atacar, movimiento restante +1.',
  '攻击后再移动过的单位，己方下回合开始前防御 +15%。': 'Las unidades que se movieron de nuevo tras atacar tienen defensa +15% hasta el inicio de tu próximo turno.',
  '强化技能「风驰」，其他效果保留。本回合：全军移动力提高到 +3，直射单位攻击后可用全部移动力再移动。': 'Mejora el poder «Como el viento»; los demás efectos se mantienen. Este turno: el movimiento de todo tu ejército sube a +3, y las unidades de fuego directo pueden moverse de nuevo tras atacar con todo su movimiento.',
  '履带车辆可以进入河流，轮式车辆可以进入沼泽，移动消耗都是 2。': 'Los vehículos de orugas pueden entrar en ríos y los vehículos de ruedas, en pantanos; el consumo de movimiento es 2 en ambos casos.',
  '强化技能「寒潮」，其他效果保留。生效期间：敌方单位在森林、山地、荒地、沼泽、河流上的移动消耗 +1（航空单位除外）。': 'Mejora el poder «Ola de frío»; los demás efectos se mantienen. Mientras está activo: el consumo de movimiento de las unidades enemigas en bosques, montañas, páramos, pantanos y ríos es +1 (excepto unidades aéreas).',
  '己方单位的地形防御也不随 HP 减少而降低。': 'La defensa de terreno de tus unidades tampoco baja al perder HP.',
  '每个敌方回合，第一个要被击毁的己方单位保留 1 HP。受攻击前 HP 至少为 5 才有效，每个单位每局一次。': 'En cada turno enemigo, tu primera unidad a punto de ser destruida conserva 1 HP. Solo se aplica si tenía al menos 5 HP antes del ataque; una vez por unidad en cada partida.',
  '强化技能「背水」，其他效果保留。攻击加成改为每损失 1 HP +10%，最多 +90%。己方下回合开始前：“咬牙”每个敌方回合可触发 3 次。': 'Mejora el poder «Sin retirada»; los demás efectos se mantienen. La bonificación de ataque pasa a ser +10% por cada 1 HP perdido, hasta +90%. Hasta el inicio de tu próximo turno: «Apretar los dientes» puede activarse 3 veces en cada turno enemigo.',
  '位于己方建筑的单位每回合免费恢复 1 HP（航空单位除外）。': 'Las unidades situadas en edificios tuyos recuperan 1 HP gratis por turno (excepto unidades aéreas).',
  '位于 2 星及以上地形或建筑的单位反击时，没有攻击 −10% 的减益。': 'Las unidades situadas en terreno de 2★ o más o en edificios no tienen la penalización de ataque −10% al contraatacar.',
  '强化技能「铁壁」，其他效果保留。恢复量提高到 3 HP。己方下回合开始前：敌方的占领不会减少己方建筑的占领值。': 'Mejora el poder «Muro de hierro»; los demás efectos se mantienen. La recuperación sube a 3 HP. Hasta el inicio de tu próximo turno: las capturas enemigas no reducen los puntos de captura de tus edificios.',
  '所有单位造价再 −5%，结果向下取整到 10 的倍数。': 'Todas las unidades tienen otro −5% de precio; el resultado se redondea hacia abajo a un múltiplo de 10.',
  '回合开始时，每持有 500 资金获得 20 资金，最多 200（上限随地图规模变化）。': 'Al inicio del turno, se obtienen 20 fondos por cada 500 fondos disponibles, hasta 200 (el límite varía según el tamaño del mapa).',
  '强化技能「军费」，其他效果保留。每座建筑的资金提高到 100。本回合：单位造价再 −20%。': 'Mejora el poder «Arcas de guerra»; los demás efectos se mantienen. Los fondos por edificio suben a 100. Este turno: las unidades tienen otro −20% de precio.',
  '运气范围变为 −5 至 +55（原来 0 至 +40）。': 'El rango de suerte pasa a ser de −5 a +55 (antes de 0 a +40).',
  '强化技能「梭哈」，其他效果保留。本回合：运气范围 ×1.5。': 'Mejora el poder «Apuesta total»; los demás efectos se mantienen. Este turno: rango de suerte ×1.5.',
  '侦察车可以占领建筑，占领值减半。不能使用导弹井。': 'El explorador puede capturar edificios, con la mitad de puntos de captura. No puede usar el silo.',
  '强化技能「穿插」，其他效果保留。被侦察车、摩托兵、运兵车穿过的敌方陆上单位各损失 1 HP（不会被击毁），每回合最多 2 HP。': 'Mejora el poder «Infiltración»; los demás efectos se mantienen. Las unidades terrestres enemigas atravesadas por exploradores, motos y portatropas pierden 1 HP (no las destruye), hasta 2 HP por turno.',
  '己方单位正在占领的敌方建筑，本回合不给敌方提供收入。': 'Los edificios enemigos que tus unidades están capturando no aportan ingresos al enemigo este turno.',
  '强化技能「加征」，其他效果保留。获得的收入提高到 150%。本回合：占领中立建筑时占领值 ×2。': 'Mejora el poder «Sobretasa»; los demás efectos se mantienen. Los ingresos obtenidos suben al 150%. Este turno: puntos de captura ×2 al capturar edificios neutrales.',
  '己方城市还可以生产侦察车和运兵车。': 'Tus ciudades también pueden producir exploradores y portatropas.',
  '不发动技能时，每回合也可以出售 1 个位于己方建筑的单位，返还造价的 40%。': 'Sin activar el poder, también se puede vender 1 unidad por turno situada en un edificio tuyo; se devuelve el 40% de su precio.',
  '强化技能「黑市」，其他效果保留。本回合：在己方城市生产的单位当回合可行动。': 'Mejora el poder «Mercado negro»; los demás efectos se mantienen. Este turno: las unidades producidas en tus ciudades pueden actuar ese mismo turno.',
});

// ── 故事与战役（lore.js、campaign.js）及改名后重新对齐的条目 ──由 tools/i18n-story.js merge 回填，固定台词见 tools/I18N-GLOSSARY.md
AWI18n.add('es', {
  '本回合：全军移动力 +3（徒步的步兵类单位 +1）、攻击 +30%。': 'Este turno: todo tu ejército tiene movimiento +3 (soldados a pie +1) y ataque +30%.',
  '本回合：全军移动力 +2。直升机攻击 +40%，其他单位攻击 +20%。直升机攻击后可再移动。': 'Este turno: todo tu ejército tiene movimiento +2. Los helicópteros tienen ataque +40% y las demás unidades, ataque +20%. Los helicópteros pueden moverse de nuevo tras atacar.',
  '全军立即恢复 2 HP。最近被击毁的一个己方单位以 1 HP 在司令部相邻的空格复活；没有空格时不复活。': 'Todo tu ejército recupera 2 HP al instante. Tu última unidad destruida revive con 1 HP en una casilla libre adyacente al cuartel general; si no hay casilla libre, no revive.',
  '本回合：全军移动力 +2。潜艇攻击 +50%，其他单位攻击 +30%。潜艇攻击时不受反击。': 'Este turno: todo tu ejército tiene movimiento +2. Los submarinos tienen ataque +50% y las demás unidades, ataque +30%. Los submarinos no reciben contraataque al atacar.',
  '本回合：全军移动力 +1。侦察车、摩托兵攻击 +40%，其他单位攻击 +20%。侦察车、摩托兵、运兵车可以穿过敌方单位，但不能停在敌方单位所在的格子。': 'Este turno: todo tu ejército tiene movimiento +1. Exploradores y motos tienen ataque +40% y las demás unidades, ataque +20%. Exploradores, motos y portatropas pueden atravesar unidades enemigas, pero no detenerse en una casilla con una unidad enemiga.',
  '本回合：步兵类单位攻击 +40%，其他单位攻击 +20%。喷火兵攻击后，目标所在的森林变为荒地，周围 2 格内的敌方单位各损失 3 HP（不会被击毁）。': 'Este turno: los soldados tienen ataque +40% y las demás unidades, ataque +20%. Tras el ataque de un lanzallamas, el bosque del objetivo se convierte en páramo y las unidades enemigas a 2 casillas o menos pierden 3 HP (no las destruye).',
  '本回合：可以出售任意己方单位，返还造价的 90%（与剩余 HP 无关）。': 'Este turno: se puede vender cualquier unidad tuya y se devuelve el 90% de su precio (sea cual sea su HP restante).',
  '在己方回合可以研究科技。': 'Las tecnologías se pueden investigar en tu turno.',
  '各档研究经费 −50%，每回合研究点 −2；上回合新占领过建筑时（每座建筑每局只算一次），本回合研究点 +4。': 'Presupuesto de investigación −50% en todos los niveles y puntos de investigación por turno −2; si en el turno anterior se capturó un edificio nuevo (cada edificio cuenta una sola vez por partida), puntos de investigación +4 este turno.',
  '强化技能「架盾」，其他效果保留。己方下回合开始前：敌方陆上单位、舰船移动到与己方直射单位相邻的格子时，先受到 50% 伤害的攻击（不会被击毁）。每个己方单位只攻击一次，敌方单位每次移动最多受到 2 次。': 'Mejora el poder «Alzar escudos»; los demás efectos se mantienen. Hasta el inicio de tu próximo turno: una unidad terrestre o un barco enemigo que se mueve junto a una unidad tuya de fuego directo recibe antes un ataque con el 50% del daño (no lo destruye). Cada unidad tuya ataca una sola vez, y la unidad enemiga recibe como máximo 2 ataques por movimiento.',
  '只有步兵这一个兵种可以穿过敌方单位所在的格子，但不能停在上面。': 'Solo la infantería (ese tipo de unidad) puede atravesar casillas con unidades enemigas, pero no detenerse en ellas.',
  '每占领一座建筑，技能槽 +10%，每回合最多 +20%。每座建筑每局只算一次，技能生效期间不算。': 'Cada edificio capturado da barra de poder +10%, hasta +20% por turno. Cada edificio cuenta una sola vez por partida, y ninguno cuenta mientras el poder está activo.',
});

