  '技术': 'Técnica',
  '按天数上限判定的胜利不评分。': 'Las victorias decididas por el límite de días no se puntúan.',
  '启用了改变规则的扩展，这一局不评分。': 'Hay un mod que cambia las reglas activado; esta partida no se puntúa.',
  '这份存档来自旧版本，这一局不评分。': 'Esta partida guardada es de una versión anterior; no se puntúa.',
  '第 {d} 天获胜，标准天数 {p} 天': 'Victoria el día {d}; días estándar: {p}',
  '击毁敌方单位造价 {a}，己方全部单位造价 {b}': 'Precio de las unidades enemigas destruidas: {a}; precio de todas tus unidades: {b}',
  '己方被击毁 {n} 个单位，造价 {a}': 'Unidades tuyas destruidas: {n}; precio: {a}',
  '总分': 'Total',
  '第一次评级': 'Primer rango',
  '新纪录': 'Nuevo récord',
  'S 评价 {a}/{b}': 'Rangos S {a}/{b}',
  '地图': 'Mapa',
  'S 评价的地图': 'Mapas con rango S',
  '困难难度 S 的地图': 'Mapas con rango S en Difícil',
  '全部地图全部指挥官 S': 'S en todos los mapas con todos los comandantes',
  'S 评价的战役关卡': 'Misiones de campaña con rango S',
  '最少天数 / 标准': 'Menos días / Estándar',
  '地图 ＼ 指挥官': 'Mapa ＼ Comandante',
  '关卡': 'Misión',
